-- 3단계(꾸미기) — 파트 B. Inventory · Scene + 아이템 정의 DB화(item_definition).
-- 공유 지도(파트 A)는 V3__shared_map.sql. MySQL 문법 기준이며 로컬 H2(MODE=MySQL)에서도 그대로 돈다.
-- 애그리거트 경계를 넘는 FK는 두지 않는다 — 루트 행(inventory·scene)만 계정 루트(explorer)를 가리킨다.
-- 집합 성격 컬럼은 V2 와 같은 이유로 VARCHAR 쉼표 구분(조회 조건이 아님, H2·MySQL validate 호환).

-- 아이템 정의(참조 데이터, 운영이 POST /admin/items 로 추가). 이관 원본: tools/catalog/items.json(지역 특산물 250)
-- + catalog sets.json 세트 배경 9 → tools/catalog/gen-item-sql.js 로 만든 INSERT(파일 끝).
--   look·color_primary·color_secondary = 엔진 룩(형태·주색·보조색, 배경은 NULL)
--   grant_rule = REGION_VISIT(grant_ref 지역 코드) | PERIOD_CHECK_IN | PROVINCE_CHECK_IN(grant_ref 시·도 코드)
--                | THEME_COMPLETE(grant_ref 세트 id) | MANUAL
--   valid_from·valid_to = 지급 유효 기간(양 끝 포함, 서버 시간대 날짜, NULL 이면 열림)
--   created_at = 정의가 생긴 시각 — 이슈 아이템(기간·시·도)은 이보다 앞선 체크인에 소급 지급하지 않는다(리더 결정 Q-R2-1)
CREATE TABLE item_definition (
    item_id         VARCHAR(60) NOT NULL,
    name            VARCHAR(40) NOT NULL,
    emoji           VARCHAR(16) NOT NULL,
    slot            VARCHAR(8)  NOT NULL,
    tier            VARCHAR(8)  NOT NULL,
    theme           VARCHAR(20) NULL,
    look            VARCHAR(20) NULL,
    color_primary   VARCHAR(7)  NULL,
    color_secondary VARCHAR(7)  NULL,
    grant_rule      VARCHAR(20) NOT NULL,
    grant_ref       VARCHAR(40) NULL,
    valid_from      DATE        NULL,
    valid_to        DATE        NULL,
    created_at      DATETIME(6) NOT NULL,
    CONSTRAINT pk_item_definition PRIMARY KEY (item_id)
);

-- Inventory 루트 행. 보유 아이템(owned_item)·방문 흔적(inventory_visit)만 바뀌어도 version 을 올려 동시 갱신을 충돌로 드러낸다.
CREATE TABLE inventory (
    explorer_id VARCHAR(36) NOT NULL,
    version     BIGINT      NOT NULL,
    updated_at  DATETIME(6) NOT NULL,
    CONSTRAINT pk_inventory PRIMARY KEY (explorer_id),
    CONSTRAINT fk_inventory_explorer FOREIGN KEY (explorer_id) REFERENCES explorer (id)
);

-- 보유 아이템. 같은 itemId 한 번만(PK). source = REGION(지역 특산물) | SET_REWARD(세트 보상) | EVENT(이슈·수동).
-- grant_kind = 받은 규칙(REGION_VISIT·PERIOD_CHECK_IN·PROVINCE_CHECK_IN 은 방문형 — 근거 방문 없이 가질 수 없어 재계산이 정리,
--              THEME_COMPLETE·MANUAL 은 근거 없이 유지). source 는 grant_kind 에서 정해지는 표시 값.
-- §4 의 map_id·region_code 는 두지 않는다 — 회수 판단은 근거 방문(owned_item_basis)으로 한다.
CREATE TABLE owned_item (
    explorer_id VARCHAR(36) NOT NULL,
    item_id     VARCHAR(60) NOT NULL,
    source      VARCHAR(12) NOT NULL,
    grant_kind  VARCHAR(20) NOT NULL,
    acquired_at DATETIME(6) NOT NULL,
    favorite    BOOLEAN     NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_owned_item PRIMARY KEY (explorer_id, item_id)
);

-- 체크인으로 받은 아이템(지역 특산물·기간/시·도 이슈)을 지금 뒷받침하는 활성 방문(지역, 지도). 받을 때의 방문과 그 뒤 같은 조건을
-- 만족한 방문이 모두 근거다. 방문 취소로 근거가 하나도 남지 않으면 아이템을 회수한다(탐험가 단위, 리더 결정 Q2).
-- 세트 보상·수동 지급은 근거 행이 없고 회수하지 않는다.
CREATE TABLE owned_item_basis (
    explorer_id VARCHAR(36) NOT NULL,
    item_id     VARCHAR(60) NOT NULL,
    region_code VARCHAR(10) NOT NULL,
    map_id      VARCHAR(36) NOT NULL,
    CONSTRAINT pk_owned_item_basis PRIMARY KEY (explorer_id, item_id, region_code, map_id)
);

-- 방문 흔적(탐험가 단위, progression explorer_region 과 같은 원리를 꾸미기가 자기 데이터로 둔다).
-- (탐험가, 지역, 지도)마다 마지막으로 반영한 방문 세대와 활성 여부 — 세대 번호 규칙으로 옛 이벤트를 무시하는 근거.
-- 행을 지우지 않고 active=false 로 남기는 이유: 늦게 다시 온 옛 세대 이벤트(재전달)를 무시하려고(세대 번호 규칙).
CREATE TABLE inventory_visit (
    explorer_id VARCHAR(36) NOT NULL,
    region_code VARCHAR(10) NOT NULL,
    map_id      VARCHAR(36) NOT NULL,
    generation  BIGINT      NOT NULL,
    active      BOOLEAN     NOT NULL,
    CONSTRAINT pk_inventory_visit PRIMARY KEY (explorer_id, region_code, map_id)
);

-- 장면(꾸미기). gender 는 Scene 이 바꾸는 값이라 여기 둔다(§4). 슬롯별 착용 아이템은 §4 의 slots JSON 대신 슬롯마다 컬럼
-- (EquipSlot 6개 고정 — 타입이 있는 컬럼이 validate·조회에 단순). props = 장식 아이템 id 최대 3개(쉼표 구분, 순서 = 배치 순서).
-- 착용 아이템 → owned_item FK 는 두지 않는다(애그리거트 경계 — 회수 시 ItemRevoked 이벤트로 벗긴다).
CREATE TABLE scene (
    explorer_id  VARCHAR(36)  NOT NULL,
    gender       VARCHAR(1)   NOT NULL,
    slot_hat     VARCHAR(60)  NULL,
    slot_hand    VARCHAR(60)  NULL,
    slot_badge   VARCHAR(60)  NULL,
    slot_bag     VARCHAR(60)  NULL,
    slot_pet     VARCHAR(60)  NULL,
    slot_bg      VARCHAR(60)  NULL,
    props        VARCHAR(200) NOT NULL,
    version      BIGINT       NOT NULL,
    updated_at   DATETIME(6)  NOT NULL,
    CONSTRAINT pk_scene PRIMARY KEY (explorer_id),
    CONSTRAINT fk_scene_explorer FOREIGN KEY (explorer_id) REFERENCES explorer (id)
);

-- ---- 아이템 정의 이관(지역 특산물 250 + 세트 배경 9) ----------------------------------------------------------
